<?php $e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$uptime=static function($date):string{if(!$date)return '—';$s=max(0,time()-strtotime((string)$date));return intdiv($s,86400).'d '.intdiv($s%86400,3600).'h '.intdiv($s%3600,60).'m';};?>
<div x-data="{open:false,search:'',status:''}" class="space-y-5"><div class="flex justify-between"><div><h1 class="text-3xl font-bold">Streams en vivo</h1><p class="text-slate-400">Estado, uptime, países conectados, fallos, reinicios y fuentes.</p></div><div class="flex gap-2"><a href="/sessions?type=live" class="bg-slate-700 px-4 py-2 rounded">Clientes y países</a><button @click="open=!open" class="bg-cyan-600 px-4 py-2 rounded">Añadir stream</button></div></div>
<form x-show="open" x-cloak method="post" action="/live" class="grid md:grid-cols-4 gap-3 bg-slate-900 border border-slate-800 rounded-xl p-5"><?=$csrf->field()?><input required name="title" placeholder="Título" class="bg-slate-800 p-2 rounded"><input type="number" name="channel_number" placeholder="Número" class="bg-slate-800 p-2 rounded"><select name="category_id" class="bg-slate-800 p-2 rounded"><option value="">Categoría</option><?php foreach($categories as $c):?><option value="<?=$c['id']?>"><?=$e($c['name'])?></option><?php endforeach?></select><input name="logo_url" placeholder="Logo URL" class="bg-slate-800 p-2 rounded"><input required type="url" name="source_url" placeholder="Fuente HTTP(S)" class="md:col-span-2 bg-slate-800 p-2 rounded"><input name="user_agent" placeholder="User-Agent" class="bg-slate-800 p-2 rounded"><input name="referer" placeholder="Referer" class="bg-slate-800 p-2 rounded"><label><input type="checkbox" name="authorized" value="1"> Fuente autorizada</label><select name="delivery_mode" class="bg-slate-800 p-2 rounded"><option value="on_demand">On-demand</option><option value="always_on">Always-on</option></select><button class="md:col-span-4 bg-cyan-600 p-2 rounded">Guardar stream</button></form>
<section class="bg-slate-900 border border-slate-800 rounded-xl p-4 grid md:grid-cols-4 gap-3"><input x-model="search" placeholder="Buscar streams..." class="md:col-span-2 bg-slate-800 p-2 rounded"><select x-model="status" class="bg-slate-800 p-2 rounded"><option value="">Todos los estados</option><option value="online">Online</option><option value="down">Down</option><option value="degraded">Degradado</option><option value="unknown">Sin comprobar</option></select><a href="/epg" class="bg-indigo-700 text-center p-2 rounded">Administrar EPG</a></section>
<div class="overflow-x-auto bg-slate-900 border border-slate-800 rounded-xl"><table class="w-full min-w-[1350px] text-sm"><thead><tr class="text-left text-xs uppercase text-slate-400"><th class="p-3">ID</th><th>Icono</th><th>Nombre</th><th>Servidor</th><th>Clientes</th><th>Uptime</th><th>Estado</th><th>Reinicios</th><th>Failovers</th><th>Acciones</th><th>EPG</th><th>Información del stream</th></tr></thead><tbody><?php foreach($channels as $c):?><tr x-show="(!search||<?=json_encode(strtolower($c['title']))?>.includes(search.toLowerCase()))&&(!status||status===<?=json_encode($c['runtime_status'])?>)" class="border-t border-slate-800 odd:bg-slate-800/35"><td class="p-3 text-slate-400"><?=$c['id']?></td><td><?php if($c['logo_url']):?><img src="<?=$e($c['logo_url'])?>" class="w-10 h-10 rounded-full object-cover" alt=""><?php else:?><span class="w-10 h-10 grid place-items-center rounded-full bg-slate-700">▶</span><?php endif?></td><td><strong><?=$e($c['title'])?></strong><div class="text-xs text-cyan-400"><?=$e($c['category']??'Sin categoría')?> · <?=$e($c['delivery_mode'])?></div><details class="mt-1"><summary class="text-xs text-slate-500 cursor-pointer"><?=$c['source_count']?> fuentes</summary><div class="absolute z-10 bg-slate-950 border border-slate-700 p-2 rounded shadow-xl"><?php foreach($c['sources'] as $s):?><div class="flex gap-3 py-1"><span>P<?=$s['priority']?></span><span><?=$e($s['name'])?></span><span class="<?=$s['status']==='healthy'?'text-emerald-400':'text-amber-400'?>"><?=$e($s['status'])?></span><span>fallos <?=$s['consecutive_failures']?></span></div><?php endforeach?></div></details></td><td><?=$e($c['server_name']??'Sin asignar')?></td><td><span class="bg-cyan-700 px-2 py-1 rounded"><?=$c['clients']?></span></td><td><?=$uptime($c['online_since'])?></td><td><span class="inline-flex min-w-24 justify-center px-3 py-2 rounded font-bold <?=$c['runtime_status']==='online'?'bg-emerald-600':($c['runtime_status']==='down'?'bg-red-600':($c['runtime_status']==='degraded'?'bg-amber-600':'bg-slate-700'))?>"><?=strtoupper($e($c['runtime_status']))?></span><div class="text-xs text-slate-500 mt-1"><?=$c['response_ms']!==null?$c['response_ms'].' ms':'Sin datos'?></div></td><td class="text-center"><strong class="text-lg"><?=$c['restart_count']?></strong></td><td class="text-center"><?=$c['failovers']?></td><td><div class="flex gap-1"><form method="post" action="/live/restart" onsubmit="return confirm('¿Reiniciar y volver a comprobar este stream?')"><?=$csrf->field()?><input type="hidden" name="channel_id" value="<?=$c['id']?>"><button title="Reiniciar" class="bg-amber-700 px-3 py-2 rounded">↻</button></form><button title="Ver fuentes" onclick="this.closest('tr').querySelector('details').open=true" class="bg-slate-700 px-3 py-2 rounded">▣</button></div></td><td><span class="inline-grid place-items-center w-8 h-8 rounded <?=$c['epg_channel_id']?'bg-emerald-600':'bg-slate-700'?>"><?=$c['epg_channel_id']?'✓':'—'?></span></td><td><div><?=$c['bitrate_kbps']?number_format($c['bitrate_kbps']).' Kbps':'Pendiente'?></div><div class="text-xs text-slate-400 flex gap-3"><span><?=$c['width']?$c['width'].'×'.$c['height']:'—'?></span><span><?=$e($c['video_codec']??'—')?></span><span><?=$e($c['audio_codec']??'—')?></span></div><div class="text-xs text-slate-500">Último OK: <?=$e($c['last_healthy_at']??'Nunca')?></div></td></tr><?php endforeach?></tbody></table></div></div>
